-- ============================================================
--  module-dispatch-config: DDL (Oracle 19C 호환)
--  생성일: 2026-07-15  /  원본: 01_schema.sql (MariaDB/MySQL)
--  변환규칙:
--    CREATE TABLE IF NOT EXISTS → DECLARE/EXECUTE IMMEDIATE (ORA-955 무시)
--    AUTO_INCREMENT             → GENERATED BY DEFAULT AS IDENTITY
--    VARCHAR(n)                 → VARCHAR2(n CHAR)
--    INT                        → NUMBER(10)
--    DEFAULT ''                 → DEFAULT ' '
--    UNIQUE KEY uk (col)        → CONSTRAINT uk UNIQUE (col) (테이블 내)
--    INDEX idx (col)            → 테이블 외부 CREATE INDEX
--    ENGINE=InnoDB ...          → 제거
--    COMMENT '...' (인라인)   → COMMENT ON COLUMN 별도 문장
--  주의: Oracle에서 IDENTITY 컬럼은 EXECUTE IMMEDIATE 문자열 내
--        홑따옴표 이스케이프('' → '''')가 필요하지 않으므로 별도 DDL로 처리
-- ============================================================

-- ── 배차 목적식 (DS_DISPATCH_OBJECTIVE) ───────────────────
-- SEQUENCE: SEQ_DS_DISPATCH_OBJECTIVE
DECLARE
BEGIN
    EXECUTE IMMEDIATE 'CREATE SEQUENCE SEQ_DS_DISPATCH_OBJECTIVE START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE';
EXCEPTION
    WHEN OTHERS THEN
        IF SQLCODE != -955 THEN RAISE; END IF;
END;
/

DECLARE
BEGIN
    EXECUTE IMMEDIATE '
        CREATE TABLE DS_DISPATCH_OBJECTIVE (
            OBJ_ID    NUMBER(10)         NOT NULL,
            OBJ_CODE  VARCHAR2(30  CHAR) NOT NULL,
            OBJ_NM    VARCHAR2(100 CHAR) NOT NULL,
            OBJ_ICON  VARCHAR2(10  CHAR) DEFAULT '' '',
            OBJ_ALGO  VARCHAR2(50  CHAR) DEFAULT '' '',
            OBJ_DESC  VARCHAR2(200 CHAR) DEFAULT '' '',
            SORT_SEQ  NUMBER(10)         DEFAULT 0,
            ACTIVE_YN VARCHAR2(1   CHAR) DEFAULT ''Y'',
            CREDAT    VARCHAR2(8   CHAR),
            LMODAT    VARCHAR2(8   CHAR),
            CONSTRAINT PK_DS_DISPATCH_OBJECTIVE PRIMARY KEY (OBJ_ID),
            CONSTRAINT UK_DS_DISPATCH_OBJ UNIQUE (OBJ_CODE)
        )
    ';
EXCEPTION
    WHEN OTHERS THEN
        IF SQLCODE != -955 THEN RAISE; END IF;
END;
/

COMMENT ON TABLE  DS_DISPATCH_OBJECTIVE           IS '배차 목적식';
COMMENT ON COLUMN DS_DISPATCH_OBJECTIVE.OBJ_ID    IS '목적식 ID (PK)';
COMMENT ON COLUMN DS_DISPATCH_OBJECTIVE.OBJ_CODE  IS '목적식 코드';
COMMENT ON COLUMN DS_DISPATCH_OBJECTIVE.OBJ_NM    IS '표시명';
COMMENT ON COLUMN DS_DISPATCH_OBJECTIVE.OBJ_ICON  IS '아이콘';
COMMENT ON COLUMN DS_DISPATCH_OBJECTIVE.OBJ_ALGO  IS '알고리즘 코드';
COMMENT ON COLUMN DS_DISPATCH_OBJECTIVE.OBJ_DESC  IS '설명';
COMMENT ON COLUMN DS_DISPATCH_OBJECTIVE.SORT_SEQ  IS '정렬순서';
COMMENT ON COLUMN DS_DISPATCH_OBJECTIVE.ACTIVE_YN IS '활성여부';
COMMENT ON COLUMN DS_DISPATCH_OBJECTIVE.CREDAT    IS '생성일자';
COMMENT ON COLUMN DS_DISPATCH_OBJECTIVE.LMODAT    IS '수정일자';


-- ── 배차 프로파일 (DS_DISPATCH_PROFILE) ───────────────────
DECLARE
BEGIN
    EXECUTE IMMEDIATE 'CREATE SEQUENCE SEQ_DS_DISPATCH_PROFILE START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE';
