            OBJECTIVE   VARCHAR2(30  CHAR) NOT NULL DEFAULT ''MIN_VEHICLES'',
            ACTIVE_YN   VARCHAR2(1   CHAR) NOT NULL DEFAULT ''Y'',
            NOTE        VARCHAR2(200 CHAR) DEFAULT '' '',
            SET_ID      NUMBER(10)         DEFAULT NULL,
            CREDAT      VARCHAR2(8   CHAR),
            LMODAT      VARCHAR2(8   CHAR),
            CONSTRAINT PK_DS_DISPATCH_PROFILE PRIMARY KEY (PROFILE_ID)
        )
