        CREATE TABLE DS_DISPATCH_CONST (
            CONST_ID    NUMBER(10)         NOT NULL,
            PROFILE_ID  NUMBER(10)         NOT NULL,
            CONST_TYPE  VARCHAR2(30  CHAR) NOT NULL,
            CONST_KEY   VARCHAR2(50  CHAR) NOT NULL,
            CONST_VALUE VARCHAR2(200 CHAR) DEFAULT NULL,
            CONST_OP    VARCHAR2(10  CHAR) DEFAULT ''<='',
            TARGET_ID   VARCHAR2(50  CHAR) DEFAULT '' '',
            TARGET_NM   VARCHAR2(100 CHAR) DEFAULT '' '',
            ACTIVE_YN   VARCHAR2(1   CHAR) DEFAULT ''Y'',
            NOTE        VARCHAR2(200 CHAR) DEFAULT '' '',
            SORT_SEQ    NUMBER(10)         DEFAULT 0,
            CREDAT      VARCHAR2(8   CHAR),
            LMODAT      VARCHAR2(8   CHAR),
            CONSTRAINT PK_DS_DISPATCH_CONST PRIMARY KEY (CONST_ID)
        )
    ';
EXCEPTION
    WHEN OTHERS THEN
        IF SQLCODE != -955 THEN RAISE; END IF;
END;
/

-- 인덱스 (테이블 외부)
DECLARE
BEGIN
    EXECUTE IMMEDIATE 'CREATE INDEX IDX_DS_CONST_PROFILE ON DS_DISPATCH_CONST (PROFILE_ID)';
EXCEPTION
    WHEN OTHERS THEN
        IF SQLCODE != -1408 THEN RAISE; END IF;
END;
/
DECLARE
BEGIN
    EXECUTE IMMEDIATE 'CREATE INDEX IDX_DS_CONST_TYPE_KEY ON DS_DISPATCH_CONST (CONST_TYPE, CONST_KEY)';
