    WHEN OTHERS THEN
        IF SQLCODE != -1408 THEN RAISE; END IF;
END;
/

COMMENT ON TABLE  DS_DISPATCH_CONST            IS '배차 제약조건 마스터';
COMMENT ON COLUMN DS_DISPATCH_CONST.CONST_ID   IS '제약 ID (PK)';
COMMENT ON COLUMN DS_DISPATCH_CONST.PROFILE_ID IS '프로파일 ID (FK)';
COMMENT ON COLUMN DS_DISPATCH_CONST.CONST_TYPE IS '제약유형';
COMMENT ON COLUMN DS_DISPATCH_CONST.CONST_KEY  IS '제약키';
COMMENT ON COLUMN DS_DISPATCH_CONST.CONST_VALUE IS '제약값';
COMMENT ON COLUMN DS_DISPATCH_CONST.CONST_OP   IS '연산자';
COMMENT ON COLUMN DS_DISPATCH_CONST.TARGET_ID  IS '적용대상ID';
COMMENT ON COLUMN DS_DISPATCH_CONST.TARGET_NM  IS '적용대상명';
COMMENT ON COLUMN DS_DISPATCH_CONST.ACTIVE_YN  IS '활성여부';
COMMENT ON COLUMN DS_DISPATCH_CONST.NOTE       IS '비고';
COMMENT ON COLUMN DS_DISPATCH_CONST.SORT_SEQ   IS '정렬순서';
COMMENT ON COLUMN DS_DISPATCH_CONST.CREDAT     IS '생성일자';
COMMENT ON COLUMN DS_DISPATCH_CONST.LMODAT     IS '수정일자';


-- ── 제약조건 항목 UI 마스터 (DS_DISPATCH_CONST_ITEM) ──────
DECLARE
BEGIN
    EXECUTE IMMEDIATE '
        CREATE TABLE DS_DISPATCH_CONST_ITEM (
            ITEM_CD     VARCHAR2(50  CHAR) NOT NULL,
            ITEM_NM     VARCHAR2(200 CHAR) NOT NULL,
            ITEM_GRP    VARCHAR2(30  CHAR) NOT NULL,
            ITEM_TYPE   VARCHAR2(20  CHAR) NOT NULL DEFAULT ''YN'',
            DEFAULT_VAL VARCHAR2(200 CHAR) DEFAULT ''Y'',
            UNIT        VARCHAR2(20  CHAR) DEFAULT '' '',
            CONST_OP    VARCHAR2(10  CHAR) DEFAULT ''='',
            SORT_SEQ    NUMBER(10)         DEFAULT 0,
            DESCRIPTION VARCHAR2(500 CHAR) DEFAULT '' '',
            SOURCE_REF  VARCHAR2(20  CHAR) DEFAULT '' '',
            ACTIVE_YN   VARCHAR2(1   CHAR) DEFAULT ''Y'',
            SELECT_OPTS VARCHAR2(500 CHAR) DEFAULT NULL,
            CREDAT      VARCHAR2(8   CHAR),
            LMODAT      VARCHAR2(8   CHAR),
            CONSTRAINT PK_DS_DISPATCH_CONST_ITEM PRIMARY KEY (ITEM_CD)
        )
    ';
EXCEPTION
    WHEN OTHERS THEN
        IF SQLCODE != -955 THEN RAISE; END IF;
END;
/

COMMENT ON TABLE  DS_DISPATCH_CONST_ITEM               IS '제약조건 항목 UI 마스터';
COMMENT ON COLUMN DS_DISPATCH_CONST_ITEM.ITEM_CD       IS '항목코드 (PK) = CONST_KEY';
COMMENT ON COLUMN DS_DISPATCH_CONST_ITEM.ITEM_NM       IS '항목명(한글)';
COMMENT ON COLUMN DS_DISPATCH_CONST_ITEM.ITEM_GRP      IS '그룹: COMMON/ROLL/BOARD/MIX/GLOBAL/CARGO/COST/DYNAMIC_ZONE/VEHICLE';
COMMENT ON COLUMN DS_DISPATCH_CONST_ITEM.ITEM_TYPE     IS '값유형: YN/NUM/TEXT/SELECT/CSV';
COMMENT ON COLUMN DS_DISPATCH_CONST_ITEM.DEFAULT_VAL   IS '기본값';
COMMENT ON COLUMN DS_DISPATCH_CONST_ITEM.UNIT          IS '단위';
COMMENT ON COLUMN DS_DISPATCH_CONST_ITEM.CONST_OP      IS '연산자';
COMMENT ON COLUMN DS_DISPATCH_CONST_ITEM.SORT_SEQ      IS '정렬순서';
COMMENT ON COLUMN DS_DISPATCH_CONST_ITEM.DESCRIPTION   IS '상세설명';
COMMENT ON COLUMN DS_DISPATCH_CONST_ITEM.SOURCE_REF    IS '참조(§번호)';
COMMENT ON COLUMN DS_DISPATCH_CONST_ITEM.ACTIVE_YN     IS '활성여부';
COMMENT ON COLUMN DS_DISPATCH_CONST_ITEM.SELECT_OPTS   IS 'SELECT 타입 옵션(JSON배열)';
COMMENT ON COLUMN DS_DISPATCH_CONST_ITEM.CREDAT        IS '생성일자';
COMMENT ON COLUMN DS_DISPATCH_CONST_ITEM.LMODAT        IS '수정일자';


