-- ── 세트별 항목 설정값 (DS_DISPATCH_CONST_SETTING) ────────
DECLARE
BEGIN
    EXECUTE IMMEDIATE 'CREATE SEQUENCE SEQ_DS_DISPATCH_CONST_SETTING START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE';
EXCEPTION
    WHEN OTHERS THEN
        IF SQLCODE != -955 THEN RAISE; END IF;
END;
/

DECLARE
BEGIN
    EXECUTE IMMEDIATE '
        CREATE TABLE DS_DISPATCH_CONST_SETTING (
            SETTING_ID  NUMBER(10)         NOT NULL,
            SET_ID      NUMBER(10)         NOT NULL,
            ITEM_CD     VARCHAR2(50  CHAR) NOT NULL,
            USE_YN      VARCHAR2(1   CHAR) NOT NULL DEFAULT ''Y'',
            SETTING_VAL VARCHAR2(200 CHAR) DEFAULT NULL,
            NOTE        VARCHAR2(200 CHAR) DEFAULT '' '',
            LMODAT      VARCHAR2(8   CHAR),
            CONSTRAINT PK_DS_DISPATCH_CONST_SETTING PRIMARY KEY (SETTING_ID),
            CONSTRAINT UK_SET_ITEM UNIQUE (SET_ID, ITEM_CD),
            CONSTRAINT FK_DSC_SETTING_SET  FOREIGN KEY (SET_ID)
                REFERENCES DS_DISPATCH_CONST_SET(SET_ID),
            CONSTRAINT FK_DSC_SETTING_ITEM FOREIGN KEY (ITEM_CD)
                REFERENCES DS_DISPATCH_CONST_ITEM(ITEM_CD)
        )
    ';
EXCEPTION
    WHEN OTHERS THEN
        IF SQLCODE != -955 THEN RAISE; END IF;
END;
/

COMMENT ON TABLE  DS_DISPATCH_CONST_SETTING              IS '세트별 항목 설정값';
COMMENT ON COLUMN DS_DISPATCH_CONST_SETTING.SETTING_ID  IS '설정 ID (PK)';
COMMENT ON COLUMN DS_DISPATCH_CONST_SETTING.SET_ID      IS '세트 ID (FK)';
COMMENT ON COLUMN DS_DISPATCH_CONST_SETTING.ITEM_CD     IS '항목코드 (FK → DS_DISPATCH_CONST_ITEM)';
COMMENT ON COLUMN DS_DISPATCH_CONST_SETTING.USE_YN      IS '사용여부';
COMMENT ON COLUMN DS_DISPATCH_CONST_SETTING.SETTING_VAL IS '설정값 오버라이드';
COMMENT ON COLUMN DS_DISPATCH_CONST_SETTING.NOTE        IS '비고';
COMMENT ON COLUMN DS_DISPATCH_CONST_SETTING.LMODAT      IS '수정일자';
